  Lemma u8jt_read : ltac2:(zQ "h30!re!u1!u6!hj2!ik8!hn7!ije!ikf!ho0!hoa!hp1!hg1!h9!hse!il5!im1!ij3!r2!r8>1m>0@1$1@1$0#k0@1$3@1$1@1$0#8>1c$c>0@2$h0$5^2>0@2$a@2$6+1^2@2$6^2+7@3$b@1$3@1$2@1$1@1$0#8@4$d$5^4@2$8@1$0#k0@2$h1$4@2$h2+4@2$7^3+1N4@2$9@1$2@1$1@1$0#8@1$f@2$8@1$0#k0@2$7@1$e^3$4").
Proof.
  intros m c MI HC.
  assert (K : exists k : nat, (k < 7)%nat /\ c = 1 + Z.of_nat k) by (exists (Z.to_nat (c - 1)); lia).
  destruct K as [k [Hk ->]].
  do 7 (destruct k as [|k]; [ match goal with |- context [ov_read_bytes _ _ (Z_to_bv 64 ?a) _] => let v := eval vm_compute in a in change a with v end; solve_load_image; f_equal; vm_compute; repeat match goal with |- (?x :: _) = (?y :: _) => apply f_equal2; [apply (proj2 (bv_eq _ x y)); vm_compute; reflexivity | ] end; reflexivity | ]).
  lia. Qed.
